-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "近戰 DPS"
L["rm.era.warrior.dps.Description"] = "1–60 級，武器與狂怒，也是所有不在防禦姿態的戰士的循環，也適用於專家模式與獨行模式伺服器；綜合 模擬器、Icy Veins 與 Wowhead。以衝鋒拉怪，對遠處目標使用攔截，三個以上敵人與你交戰時使用旋風斬（學會前用雷霆一擊），接著低於 20% 時優先使用斬殺，對沒有破甲的首領疊滿五層破甲攻擊，嗜血，致死打擊，擁有強化猛擊時在揮擊後立即使用猛擊（針對雙手武器設定；可在複製的循環中修改），保留主要打擊所需怒氣的同時使用旋風斬，壓制，學會主要打擊之前使用撕裂，對生命力充足的目標使用破甲攻擊，怒氣接近上限時使用斷筋。提醒：戰鬥怒吼、40 點怒氣起使用英勇打擊（升級期間為 20 點）、怪群時使用順劈斬、血性狂暴、橫掃攻擊、死亡之願（首領：最後 30 秒）、搭配死亡之願使用魯莽、拳擊或盾擊。破膽怒吼與反擊風暴列出但預設關閉，供專家模式緊急時使用；姿態切換由你自行處理。"
L["rm.era.warrior.protection.Name"] = "坦克"
L["rm.era.warrior.protection.Description"] = "只要你處於防禦姿態就會選用（防護、狂怒防護或雙手武器坦克）；綜合 Icy Veins 與 MaxDps。四個以上敵人時：為了威脅值使用挫志怒吼與戰鬥怒吼。接著是復仇、盾牌猛擊、嗜血、疊滿五層破甲攻擊、對精英使用挫志怒吼、破甲攻擊作為填充，以及在學會盾牌猛擊或嗜血之前使用撕裂。盾牌猛擊與盾牌格擋只在裝備盾牌時使用。提醒：戰鬥怒吼、目標正在攻擊你時使用盾牌格擋、血性狂暴、50 點怒氣起使用英勇打擊與順劈斬、盾擊、破釜沉舟。嘲諷、盾牆與死亡之願列出但預設關閉；為斬殺切換到戰鬥姿態（由傷害內建循環接手）與挑戰怒吼由你自行處理。"
L["rm.era.warrior.protection.icyveins.Name"] = "坦克，戰鬥怒吼威脅值（Icy Veins）"
L["rm.era.warrior.protection.icyveins.Description"] = "Icy Veins 的「無破甲」坦克打法，適用於有四名以上玩家能受到你怒吼影響的隊伍（第 5 階段戰鬥怒吼之後），作為推薦的坦克內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。維持挫志怒吼，復仇，盾牌猛擊或嗜血，然後以戰鬥怒吼取代破甲攻擊作為威脅值填充；盾牌猛擊與盾牌格擋只在裝備盾牌時使用。提醒與推薦的坦克內建循環相同；在一群敵人中專注單一目標時改回破甲攻擊。"
L["rm.forever.warrior.dps.Name"] = "武器與狂怒（Icy Veins）"
L["rm.forever.warrior.dps.Description"] = "武器與狂怒近戰，適用於 1 至 60 級，也是所有不在防禦姿態的戰士的預設循環。永久版本中怒氣稀少且對插件隱藏，因此只在致死打擊或嗜血恢復期間才把怒氣花在其他技能上，藉此累積怒氣：以衝鋒拉怪、勝利衝擊、攔截，斬殺（在其範圍內）用於精英、首領或隊伍中，旋風斬或雷霆一擊，怪群時挫志怒吼與猛擊，對巨人與龍類使用穿刺打擊，學會嗜血前使用撕裂、壓制、致死打擊、嗜血，然後旋風斬，站著不動時猛擊，兩層破甲攻擊（對精英疊五層）。提醒：戰鬥怒吼、血性狂暴、中斷施法、主要攻擊恢復期間的英勇打擊、怪群時的順劈斬、橫掃攻擊、死亡之願與狂暴之怒；魯莽與反擊風暴已列出但預設關閉。由你自行處理：姿態切換、斷筋與消耗品。"
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "武器與狂怒，傾瀉怒氣（Warcraft Tavern）"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "Warcraft Tavern 用於隊伍與團隊的持續傾瀉怒氣清單：先疊五層破甲攻擊，目標低於 20% 時斬殺優先於一切，壓制，學會嗜血前使用撕裂，致死打擊、嗜血、旋風斬，穿刺打擊冷卻結束即使用，點了強化猛擊後使用猛擊；只要負擔得起就使用英勇打擊或順劈斬（永久版本中怒氣是隱藏的，因此沒有 60 怒氣門檻，也沒有怒氣有餘時的斷筋），魯莽冷卻結束即使用並同時使用死亡之願。如果你在隊伍中遊戲，不需要在兩次拉怪之間保留怒氣，請選擇它而非 Icy Veins 內建循環。這是推薦的近戰傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.forever.warrior.protection.Name"] = "防護（Icy Veins）"
L["rm.forever.warrior.protection.Description"] = "10 至 60 級，只要你處於防禦姿態就作為坦克循環。以衝鋒拉怪（擁有守禦先鋒後可在防禦姿態下衝鋒）、勝利衝擊，兩個以上敵人時雷霆一擊冷卻結束即使用、挫志怒吼、盾牌猛擊、復仇與撕裂。單一目標時：盾牌猛擊、復仇、挫志怒吼、撕裂、破甲攻擊（對精英疊五層），以及對危險目標使用雷霆一擊。提醒：戰鬥怒吼、血性狂暴、盾擊、你持有目標仇恨時的盾牌格擋、盾牌猛擊與復仇都在恢復時的英勇打擊，以及怪群時的順劈斬；嘲諷與盾牆已列出但預設關閉。在永久版本中，插件看不到怒氣、生命力與目標的法力，因此怒氣門檻、施法者與破釜沉舟由你決定。由你自行處理：學會守禦先鋒之前切換到戰鬥姿態衝鋒、嘲諷其他敵人以及拉回跑掉的敵人。"
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "防護，維持減益（Warcraft Tavern）"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "Warcraft Tavern 的坦克順序：先在每個目標上維持雷霆一擊、挫志怒吼與五層破甲攻擊，然後是復仇、撕裂，最後是盾牌猛擊，只要負擔得起就使用英勇打擊或順劈斬（永久版本中怒氣是隱藏的，因此沒有 60 怒氣的門檻）。沒有盾牌格擋或防禦提醒。如果你偏好先維持減益效果，請選擇它而非 Icy Veins 坦克內建循環。這是推薦的防護內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.mop.warrior.arms.Name"] = "推薦"
L["rm.mop.warrior.arms.Description"] = "推薦 10 至 90 級的武器使用，在武器專精中選用。以衝鋒開場，離開目標時再次衝鋒以獲得怒氣。巨像碎擊缺少或即將結束時使用巨像碎擊，致死打擊，巨像碎擊期間使用暴風怒擲，巨像碎擊期間以外使用龍吼與劍刃風暴。目標生命力低於 20% 時：巨像碎擊期間、100 點怒氣時或為了維持就地處決時使用斬殺，血腥體驗觸發時使用壓制。其他情況：巨像碎擊期間使用猛擊，四層血腥體驗時使用壓制，100 點怒氣時使用猛擊，壓制，猛擊。兩個以上敵人與你交戰時加入橫掃攻擊、為了重傷使用雷霆一擊、劍刃風暴與龍吼。生命力低於 70% 時使用勝利衝擊；為了怒氣使用戰鬥怒吼。提醒：沒有怒吼時施放怒吼、戰鬥姿態、狂暴之怒、長時間戰鬥時搭配巨像碎擊使用魯莽、化身與浴血、骷髏戰旗、怒氣有餘時使用英勇打擊或順劈斬、巨像碎擊期間使用英勇躍擊、拳擊、生命力低時使用劍下亡魂與狂怒恢復。碎甲投擲列出但預設關閉。由你自行處理：取消劍刃風暴、姿態切換與站位。"
L["rm.mop.warrior.arms.icyveins.Name"] = "為巨像碎擊蓄積怒氣（Icy Veins）"
L["rm.mop.warrior.arms.icyveins.Description"] = "預設關閉。Icy Veins 與 Wowhead 的武器順序：巨像碎擊期間以外，只使用壓制，並只在怒氣高於 80 時使用猛擊，把怒氣留到巨像碎擊期間，而不是以猛擊作為填充。巨像碎擊期間：致死打擊、猛擊、壓制、英勇投擲。目標生命力低於 20% 時：巨像碎擊、致死打擊、斬殺、壓制、龍吼。兩個敵人時使用橫掃攻擊，三個以上時使用以雷霆一擊為主的怪群清單。英勇打擊或順劈斬只在怒氣接近上限時使用。提醒與推薦的武器內建循環相同。要使用它，請啟用它並停用推薦的循環。"
L["rm.mop.warrior.fury.Name"] = "推薦"
L["rm.mop.warrior.fury.Description"] = "推薦 10 至 90 級的狂怒使用，在狂怒專精中選用。以衝鋒開場並用來獲得怒氣。累積兩層狂怒之擊充能後（魯莽期間為一層）使用巨像碎擊，巨像碎擊即將結束時使用狂怒之擊，嗜血，巨像碎擊，暴風怒擲，巨像碎擊期間以外使用龍吼，使用一心狂怒（單手武器）時在此使用斬殺，嗜血冷卻時使用劍刃風暴，使用泰坦之握（雙手武器）時在巨像碎擊期間以外再使用一次狂怒之擊，斬殺，熱血沸騰觸發時使用狂野打擊，保留一層充能給下一次巨像碎擊的狂怒之擊，狂野打擊，英勇投擲，為了怒氣使用戰鬥怒吼。兩個以上敵人與你交戰時加入劍刃風暴、龍吼、為了削骨斬肉使用旋風斬，以及順劈的狂怒之擊。提醒：沒有怒吼時施放怒吼、戰鬥姿態、為了狂怒使用狂暴之怒、長時間戰鬥時搭配巨像碎擊使用魯莽、化身與浴血、骷髏戰旗、怒氣有餘時使用英勇打擊或順劈斬、英勇躍擊、拳擊，以及生命力低時使用防禦技能。由你自行處理：取消劍刃風暴。"
L["rm.mop.warrior.fury.icyveins.Name"] = "巨像碎擊期間使用冷卻技能（Icy Veins）"
L["rm.mop.warrior.fury.icyveins.Description"] = "預設關閉。Icy Veins 的狂怒順序會在巨像碎擊期間優先使用劍刃風暴或龍吼，並在目標生命力低於 20% 時將斬殺排在嗜血之前。巨像碎擊期間以外：巨像碎擊、嗜血、只在兩層充能時使用狂怒之擊、熱血沸騰觸發時使用狂野打擊、怒吼、狂野打擊。四個以上敵人時：為了狂怒使用嗜血、以旋風斬疊到三層削骨斬肉、狂怒之擊。英勇打擊或順劈斬只在怒氣接近上限時使用。提醒與推薦的狂怒內建循環相同。要使用它，請啟用它並停用推薦的循環。"
L["rm.mop.warrior.protection.Name"] = "推薦"
L["rm.mop.warrior.protection.Description"] = "10 至 90 級的坦克，在防護專精下選用。以衝鋒或英勇投擲拉怪。對精英與首領以挫敗維持三層弱化護甲，龍吼，劍刃風暴，三個敵人時使用震懾波，三個以上時雷霆一擊冷卻結束即使用。接著在盾牌格擋的最後階段以復仇消耗怒氣，盾牌猛擊，堅守陣線觸發時使用復仇，為了重傷使用挫敗，生命力低於 60% 時使用勝利衝擊，復仇，為了弱化攻擊使用雷霆一擊，斬殺，暴風怒擲，為了怒氣使用怒吼，以及挫敗（26 級前為破甲攻擊）。提醒：防禦姿態、沒有怒吼時施放怒吼、盾牌格擋未生效時就使用、受傷且怒氣有餘時使用盾牌屏障、最終通牒、激動觸發或怒氣接近上限時使用英勇打擊或順劈斬、挫志怒吼、狂暴之怒、生命力低時使用狂怒恢復、破釜沉舟與盾牆、你的攻擊性冷卻技能、拳擊。嘲諷與英勇躍擊列出但預設關閉。由你自行處理：要嘲諷誰，以及面對魔法時選擇盾牌格擋或盾牌屏障。"
L["rm.mop.warrior.unspecialized.Name"] = "未選擇專精"
L["rm.mop.warrior.unspecialized.Description"] = "適用於 1 至 9 級，或直到你選擇專精為止。以衝鋒拉怪，勝利衝擊，斬殺，以及有 30 點怒氣時使用英勇打擊；若你沒有處於任何姿態，會提醒你進入戰鬥姿態。"
L["rm.retail.warrior.arms.Name"] = "暴雪戰鬥助手"
L["rm.retail.warrior.arms.Description"] = "推薦至暗之夜的武器專精使用。在戰鬥中，遊戲現在會對插件隱藏怒氣、撕裂、千鈞潰擊、觸發效果、冷卻時間與生命力，因此它會顯示暴雪自己的戰鬥助手建議（一鍵循環），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：英勇打擊（建議從不使用的核心按鍵）、戰鬥中的巨像化身與勇士之矛、兩波拉怪之間的戰鬥怒吼、對可中斷的施法使用拳擊（只會在遊戲允許讀取該施法的場合亮起）、戰鬥中只要就緒就使用劍下亡魂（正式版中生命力是隱藏的，因此何時使用由你決定）。"
L["rm.retail.warrior.arms.colossus.Name"] = "巨像參考（SimulationCraft）"
L["rm.retail.warrior.arms.colossus.Description"] = "僅供參考，預設關閉：來自 SimulationCraft 與 Icy Veins 的巨像施放順序以致死打擊累積巨像之力，並需要讀取至暗之夜在戰鬥中隱藏的增益效果。以衝鋒開場；兩個以上敵人時使用橫掃攻擊；巨像之力少於五層時使用致死打擊；在千鈞潰擊之前使用撕裂；劫毀旋刃；兩層驟亡時使用斬殺；千鈞潰擊；勇士之矛；千鈞潰擊期間且有巨像之力時使用毀壞；英勇打擊；致死打擊；斬殺；壓制；撕裂剩餘不到 5 秒時使用撕裂；兩個以上敵人時使用劍刃風暴；猛擊。提醒：巨像化身、劍下亡魂、戰鬥怒吼、拳擊。"
L["rm.retail.warrior.arms.slayer.Name"] = "殺戮者參考（SimulationCraft）"
L["rm.retail.warrior.arms.slayer.Description"] = "僅供參考，預設關閉：來自 SimulationCraft、Icy Veins 與 Wowhead 的殺戮者施放順序需要讀取怒氣、撕裂、千鈞潰擊、驟亡與伺機而動，而至暗之夜會在戰鬥中隱藏它們。以衝鋒開場；面對兩個以上交戰中的敵人時使用橫掃攻擊；撕裂即將結束時在千鈞潰擊之前使用撕裂；在千鈞潰擊之前使用劫毀旋刃；兩層驟亡時使用斬殺；千鈞潰擊；千鈞潰擊或巨像化身期間使用劍刃風暴；英勇打擊；兩層伺機而動時使用壓制；致死打擊；斬殺；壓制；撕裂剩餘不到 5 秒時使用撕裂；猛擊。提醒：千鈞潰擊就緒時使用巨像化身、劍下亡魂、戰鬥怒吼、拳擊。"
L["rm.retail.warrior.fury.Name"] = "暴雪戰鬥助手"
L["rm.retail.warrior.fury.Description"] = "推薦至暗之夜的狂怒專精使用。顯示暴雪的戰鬥助手建議（暴怒、嗜血、狂怒之擊、斬殺、歐丁之怒與劍刃風暴），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：戰鬥中的魯莽、巨像化身與勇士之矛、兩波拉怪之間的戰鬥怒吼、拳擊、戰鬥中只要就緒就使用狂怒恢復（正式版中生命力是隱藏的，因此何時使用由你決定）。"
L["rm.retail.warrior.fury.slayer.Name"] = "殺戮者參考（SimulationCraft）"
L["rm.retail.warrior.fury.slayer.Description"] = "僅供參考，預設關閉：SimulationCraft 的殺戮者施放順序需要讀取狂怒、魯莽與驟亡，而至暗之夜會在戰鬥中隱藏它們；正式版中怒氣是隱藏的，因此暴怒只等待自身的消耗。以衝鋒開場；面對兩個以上交戰中的敵人時為取得增益效果使用旋風斬；狂怒即將結束時使用暴怒；魯莽期間：暴怒，劍刃風暴，驟亡觸發時使用斬殺，歐丁之怒；碾擊；浴血；斬殺；歐丁之怒；狂怒之擊；暴怒；嗜血；旋風斬。提醒：魯莽、巨像化身、狂怒恢復、戰鬥怒吼、拳擊。"
L["rm.retail.warrior.fury.thane.Name"] = "山脈族長參考（Icy Veins）"
L["rm.retail.warrior.fury.thane.Description"] = "僅供參考，預設關閉：來自 SimulationCraft 與 Icy Veins 的山脈族長施放順序會穿插雷霆暴擊，並需要讀取至暗之夜在戰鬥中隱藏的增益效果。以衝鋒開場；兩個以上敵人時為取得增益效果使用旋風斬；狂怒消失或即將結束時使用暴怒（正式版中怒氣是隱藏的，因此沒有怒氣達到 100 的暴怒）；魯莽期間使用浴血；兩層時使用雷霆暴擊；碾擊；浴血；魯莽期間使用暴怒；巨像化身期間使用雷霆暴擊；狂怒之擊；雷霆暴擊；暴怒；嗜血；斬殺；歐丁之怒；雷霆一擊；旋風斬。提醒與殺戮者參考循環相同。"
L["rm.retail.warrior.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.warrior.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是戰士的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個戰士內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.warrior.protection.Name"] = "暴雪戰鬥助手"
L["rm.retail.warrior.protection.Description"] = "推薦至暗之夜的防護專精使用。顯示暴雪針對傷害與威脅值的戰鬥助手建議，並在你施法或沒有選取敵人時停止。該建議從不施放盾牌格擋或無視苦痛，因此只要它們可用且你的目標正在攻擊你，兩者都會作為提醒亮起；遊戲會隱藏怒氣，因此無視苦痛亮起的次數會比你實際需要的更多。其他提醒：戰鬥中的巨像化身、挫志怒吼與勇士之矛、戰鬥中只要就緒就使用盾牆與破釜沉舟（正式版中生命力是隱藏的，因此何時使用由你決定）、在隊伍中你的目標攻擊其他人時使用嘲諷、兩波拉怪之間的戰鬥怒吼、拳擊。"
L["rm.retail.warrior.protection.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.warrior.protection.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序需要讀取盾牌格擋、雷霆暴擊與巨像之力，而至暗之夜會在戰鬥中隱藏它們；正式版中怒氣與生命力是隱藏的。以衝鋒開場；劫毀旋刃；兩層時使用雷霆暴擊；巨像之力達到五層時使用毀壞；盾牌衝鋒；雷霆暴擊；盾牌猛擊；雷霆一擊；斬殺；復仇；挫敗。提醒：盾牌格擋增益效果消失且你正在坦克時使用盾牌格擋、無視苦痛、巨像化身、挫志怒吼、勇士之矛、戰鬥中只要就緒就使用盾牆與破釜沉舟、戰鬥怒吼、拳擊。"
L["rm.sod.warrior.dps.Name"] = "近戰 DPS（探索賽季）"
L["rm.sod.warrior.dps.Description"] = "探索賽季，1–60 級，符文會在你紋刻後納入使用：雙手武器、雙持、鬥士姿態與升級皆可，也是所有不在防禦姿態的探索賽季戰士的循環；綜合 模擬器 第 6 階段與 Wowhead 第 7/8 階段。衝鋒、勝利衝擊、攔截、兩個以上敵人時使用旋風斬（學會前用雷霆一擊）、三層猛烈一擊時使用猛擊、維持撕裂、鮮血澎湃時使用猛擊（紋刻精準時機後則冷卻結束即使用）、嗜血、致死打擊、盾牌猛擊（裝備盾牌時）、壓制；然後已紋刻快速打擊時使用它（雙手武器），否則使用旋風斬、狂怒之擊與挫敗（學會前用破甲攻擊）；30 點怒氣或驟亡觸發時使用斬殺；怒氣接近上限時使用斷筋。提醒：戰鬥怒吼與命令之吼、50 點怒氣起使用英勇打擊（怒火攻心使你狂怒時一律使用）、順劈斬、血性狂暴、暴怒、死亡之願、魯莽、橫掃攻擊、中斷施法。狂暴之怒與為血腥體驗短暫切換到戰鬥姿態列出但預設關閉。"
L["rm.sod.warrior.dps.icyveins.Name"] = "近戰 DPS（探索賽季，Icy Veins）"
L["rm.sod.warrior.dps.icyveins.Description"] = "Icy Veins 的探索賽季狂怒與武器頁面，作為推薦的探索賽季近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。低於 20% 或驟亡觸發時以接近最高的優先順序使用斬殺，鮮血澎湃時使用猛擊，嗜血或致死打擊，旋風斬，壓制，狂怒之擊，然後只有在怒氣高於 60 時才使用快速打擊與斷筋；不使用撕裂；英勇打擊只在怒氣高於 80 時使用。提醒與推薦的內建循環相同。"
L["rm.sod.warrior.dps.wowhead.Name"] = "戰鬥預報者姿態切換（探索賽季，Wowhead）"
L["rm.sod.warrior.dps.wowhead.Description"] = "Wowhead 第 7/8 階段針對戰鬥預報者之魂或 T1 六件套裝的循環（Rotation Master 無法看到這些），作為推薦的探索賽季近戰傷害輸出內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。切換姿態以維持預報增益效果，幾乎總是使用英勇打擊，然後是嗜血、鮮血澎湃猛擊、旋風斬、狂怒之擊與斷筋；不使用撕裂與壓制。依賴它之前請先在遊戲中確認切換時機。"
L["rm.sod.warrior.tank.Name"] = "坦克（探索賽季）"
L["rm.sod.warrior.tank.Description"] = "探索賽季的坦克，處於防禦姿態時選用；綜合 Wowhead 第 8 階段與 模擬器。衝鋒；兩個以上敵人時使用雷霆一擊、震懾波、盾牌猛擊、復仇、旋風斬與挫敗；接著防衛者的決心缺少或即將結束時使用盾牌猛擊，復仇，盾牌猛擊，震懾波，斬殺，五層鬥士的狡詐時使用旋風斬，挫敗（學會前用破甲攻擊），對精英使用挫志怒吼與雷霆一擊，學會盾牌猛擊之前使用撕裂；盾牌猛擊與盾牌格擋只在裝備盾牌時使用。提醒：戰鬥怒吼與命令之吼、盾牌格擋、50 點怒氣起使用英勇打擊、55 點起使用順劈斬、血性狂暴、暴怒、破釜沉舟、中斷施法。嘲諷、盾牆、死亡之願、魯莽與反擊風暴列出但預設關閉；為斬殺切換鬥士姿態由你自行處理。"
L["rm.tbc.warrior.dps.icyveins.Name"] = "近戰 DPS（Icy Veins）"
L["rm.tbc.warrior.dps.icyveins.Description"] = "1–70 級，武器或狂怒，遵循 Icy Veins。拉怪、提醒與升級步驟都與 模擬器 版本相同，但有致死打擊時斬殺排在最前，有嗜血時斬殺緊接在後，旋風斬接著使用且不保留怒氣，斷筋只在怒氣接近全滿時使用。猛擊時機、姿態切換與狂暴之怒由你自行處理。這是推薦的 模擬器 近戰傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.tbc.warrior.dps.simulator.Name"] = "近戰 DPS（模擬器）"
L["rm.tbc.warrior.dps.simulator.Description"] = "1–70 級，武器或狂怒。以衝鋒拉怪，接著是勝利衝擊、攔截、暴怒，兩個以上敵人與你交戰時使用旋風斬（學會前為雷霆一擊）。擁有嗜血或致死打擊時：使用該打擊、怒氣有餘時旋風斬、斬殺、壓制。學會它們之前：旋風斬、斬殺、壓制、撕裂。多餘的怒氣用於挫敗或破甲攻擊，然後是斷筋。會提醒你戰鬥怒吼、血性狂暴、以英勇打擊或順劈斬消耗怒氣、橫掃攻擊、死亡之願、魯莽以及中斷施法。猛擊時機、姿態切換與狂暴之怒由你自行處理。"
L["rm.tbc.warrior.protection.icyveins.Name"] = "坦克（Icy Veins）"
L["rm.tbc.warrior.protection.icyveins.Description"] = "10–70 級，處於防禦姿態時選用，遵循 Icy Veins。盾牌猛擊、復仇，然後是挫敗或破甲攻擊，學會盾牌猛擊之前在戰鬥開始時使用撕裂。怪群時：雷霆一擊，對精英使用挫志怒吼。只要目標正在攻擊你且你裝備了盾牌，就會提醒盾牌格擋。嘲諷與其他輔助技能由你自行處理。這是推薦的 Wowhead 坦克內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.tbc.warrior.protection.wowhead.Name"] = "坦克（Wowhead）"
L["rm.tbc.warrior.protection.wowhead.Description"] = "10–70 級，處於防禦姿態時選用。盾牌猛擊、復仇，對精英與首領維持雷霆一擊與挫志怒吼，然後是挫敗或破甲攻擊。怪群時：先雷霆一擊與挫志怒吼。會提醒你對首領與等級較高的敵人使用盾牌格擋（需裝備盾牌）、英勇打擊或順劈斬、戰鬥怒吼、血性狂暴、盾擊，以及緊急時的破釜沉舟與盾牆。嘲諷與其他輔助技能由你自行處理。"
